function dilution(c1, v1, c2, v2){
  // 求解缺失的那一项（其余三项已知）
  if(c1==null || isNaN(c1)) return c2*v2/v1;
  if(v1==null || isNaN(v1)) return c2*v2/c1;
  if(c2==null || isNaN(c2)) return c1*v1/v2;
  if(v2==null || isNaN(v2)) return c1*v1/c2;
  return c1*v1; // 全已知 -> 给出 C1*V1（与 C2*V2 应相等）
}
var EXPORTS = { dilution:dilution };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DilutionForgePure = EXPORTS; }
